class ArtMethodMangler {
  constructor (opaqueMethodId) {
    this.methodId = unwrapMethodId(opaqueMethodId);
    this.requiresDirectCall = true;
    this.hookedMethodId = this.methodId;
    this.originalMethod = null;
    this.replacementMethodId = null;
  }

  replace (impl, isInstanceMethod, argTypes, vm, api) {
    if (this.originalMethod !== null) {
      throw new Error('Direct ART method is already replaced');
    }
    if (!['arm', 'arm64'].includes(Process.arch) || getAndroidApiLevel() < 23) {
      throw new Error('Direct ART experiment requires Android >= 6.0 on ARM');
    }

    const originalMethod = fetchArtMethod(this.hookedMethodId, vm);
    const originalFlags = originalMethod.accessFlags;
    if ((originalFlags & kAccXposedHookedMethod) !== 0 && xposedIsSupported()) {
      throw new Error('Direct ART experiment does not support Xposed method wrappers');
    }
    const { kAccCompileDontBother, artNterpEntryPoint } = api;
    const quickCode = originalMethod.quickCode;
    const isNterp = artNterpEntryPoint !== null && quickCode.equals(artNterpEntryPoint);
    if (!isNterp && !isArtQuickEntrypoint(quickCode)) {
      throw new Error('Direct ART experiment requires a non-compiled method entrypoint');
    }

    const replacementMethodId = cloneArtMethod(this.hookedMethodId, vm);
    let removedFlags = kAccFastInterpreterToInterpreterInvoke | kAccSingleImplementation | kAccNterpEntryPointFastPathFlag;
    if ((originalFlags & kAccNative) === 0) {
      removedFlags |= kAccSkipAccessChecks;
    }
    patchArtMethod(replacementMethodId, {
      accessFlags: ((originalFlags & ~removedFlags) | kAccCompileDontBother) >>> 0,
      quickCode: isNterp ? api.artQuickToInterpreterBridge : quickCode
    }, vm);

    // Keep clone class references synchronized by the existing GC hooks.
    ensureArtKnowsHowToHandleReplacementMethods(vm);
    artController.replacedMethods.set(this.hookedMethodId, replacementMethodId);
    try {
      patchArtMethod(this.hookedMethodId, {
        jniCode: impl,
        accessFlags: ((originalFlags & ~(kAccCriticalNative | kAccFastNative | kAccNterpEntryPointFastPathFlag)) |
          kAccNative | kAccCompileDontBother) >>> 0,
        quickCode: api.artClassLinker.quickGenericJniTrampoline,
        interpreterCode: api.artInterpreterToCompiledCodeBridge
      }, vm);
    } catch (e) {
      try {
        patchArtMethod(this.hookedMethodId, originalMethod, vm);
      } finally {
        artController.replacedMethods.delete(this.hookedMethodId);
      }
      throw e;
    }
    this.originalMethod = originalMethod;
    this.replacementMethodId = replacementMethodId;
  }

  revert (vm) {
    if (this.originalMethod === null) {
      return;
    }
    patchArtMethod(this.hookedMethodId, this.originalMethod, vm);
    artController.replacedMethods.delete(this.hookedMethodId);
    this.originalMethod = null;
    this.replacementMethodId = null;
  }

  resolveTarget (wrapper, isInstanceMethod, env, api) {
    if (this.replacementMethodId === null) {
      throw new Error('Direct ART method has no original-call clone');
    }
    return this.replacementMethodId;
  }
}

methodId = mangler.resolveTarget(receiver, isInstanceMethod, env, api);
if (mangler.requiresDirectCall === true) {
  strategy = STRATEGY_DIRECT;
}

try {
  mangler.replace(replacement, type === INSTANCE_METHOD, argTypes, vm, api);
} catch (e) {
  this._r = undefined;
  throw e;
}
